// Une la respuesta de OWM (por indice) con las ciudades, agrega a 3 dias
// (TZ Argentina UTC-3) y mapea a la clave de ilustracion. Devuelve {edicion_id, rows[78]}.
// owmToClave replicado de src/lib/clima/condiciones.ts -> mantener en sync.
const OFFSET = -10800; // UTC-3 en segundos
const VIENTO_UMBRAL_MS = 9;
const SET_LLUVIA_INTENSA = new Set([502,503,504,522,531]);
const SET_AGUANIEVE = new Set([611,612,613,615,616]);
const PISABLES = new Set(["despejado","parcialmente-nublado","nublado"]);

function owmToClave(owmId, windSpeedMs){
  let clave;
  if (owmId>=200 && owmId<=232) clave="tormenta";
  else if (owmId>=600 && owmId<=622){
    if (owmId===602||owmId===622) clave="nieve-intensa";
    else if (SET_AGUANIEVE.has(owmId)) clave="aguanieve";
    else clave="nieve";
  } else if (owmId>=500 && owmId<=531){
    if (SET_LLUVIA_INTENSA.has(owmId)) clave="lluvia-intensa";
    else if (owmId===511) clave="llovizna";
    else clave="lluvia";
  } else if (owmId>=300 && owmId<=321) clave="llovizna";
  else if (owmId>=701 && owmId<=781) clave=(owmId===701||owmId===721)?"neblina":"niebla";
  else if (owmId===800) clave="despejado";
  else if (owmId===801||owmId===802) clave="parcialmente-nublado";
  else if (owmId===803||owmId===804) clave="nublado";
  else clave="parcialmente-nublado";
  if (PISABLES.has(clave) && windSpeedMs>=VIENTO_UMBRAL_MS) clave="viento";
  return clave;
}

const ciudades = $('Ciudades').all().map((i)=>i.json);
const respuestas = $input.all().map((i)=>i.json);
const rows = [];

for (let c=0; c<ciudades.length; c++){
  const city = ciudades[c];
  const data = respuestas[c] || {};
  const list = Array.isArray(data.list) ? data.list : [];
  const dias = {};
  for (const e of list){
    const d = new Date((e.dt + OFFSET) * 1000);
    const y = d.getUTCFullYear();
    const m = String(d.getUTCMonth()+1).padStart(2,"0");
    const day = String(d.getUTCDate()).padStart(2,"0");
    const fecha = y+"-"+m+"-"+day;
    const hour = d.getUTCHours();
    const tmin = e.main ? e.main.temp_min : null;
    const tmax = e.main ? e.main.temp_max : null;
    const wid = (e.weather && e.weather[0]) ? e.weather[0].id : 800;
    const wdesc = (e.weather && e.weather[0]) ? e.weather[0].description : null;
    const wind = e.wind ? (e.wind.speed || 0) : 0;
    const diff = Math.abs(hour-13);
    if (!dias[fecha]){
      dias[fecha] = { min:tmin, max:tmax, wind, repId:wid, repDesc:wdesc, repDiff:diff };
    } else {
      const dd = dias[fecha];
      if (tmin!=null && (dd.min==null || tmin<dd.min)) dd.min=tmin;
      if (tmax!=null && (dd.max==null || tmax>dd.max)) dd.max=tmax;
      if (wind>dd.wind) dd.wind=wind;
      if (diff<dd.repDiff){ dd.repDiff=diff; dd.repId=wid; dd.repDesc=wdesc; }
    }
  }
  const fechas = Object.keys(dias).sort().slice(0,3);
  for (const f of fechas){
    const dd = dias[f];
    rows.push({
      edicion_id: city.edicion_id,
      provincia: city.id,
      fecha: f,
      temperatura_min: dd.min!=null ? Math.round(dd.min) : null,
      temperatura_max: dd.max!=null ? Math.round(dd.max) : null,
      condicion: dd.repDesc,
      icono: owmToClave(dd.repId, dd.wind),
    });
  }
}

const edicionId = ciudades.length ? ciudades[0].edicion_id : null;
return [{ json: { edicion_id: edicionId, rows } }];
